/* Main container */
.quiz-container {
    max-width: 700px;
    margin: 0 auto;
    padding: 2rem;
    background-color: var(--secondary-bg);
    border-radius: 12px;
    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 10px 10px -5px rgba(0, 0, 0, 0.3);
}

h1 {
    margin: 0 0 0.5rem 0;
    font-size: 2rem;
    font-weight: 600;
    color: var(--text-primary);
    background: linear-gradient(135deg, var(--accent-color-light), var(--focus-color-light));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.quiz-subtitle {
    margin: 0 0 2rem 0;
    color: var(--text-secondary);
    font-size: 1rem;
}

/* Form fields */
.form-field {
    margin-bottom: 2rem;
    padding: 1.5rem;
    background-color: var(--tertiary-bg);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    transition: var(--transition);
}

.form-field:hover {
    border-color: var(--accent-color);
    background-color: rgba(51, 65, 85, 0.8);
}

fieldset {
    margin: 0;
    padding: 0;
    border: none;
}

legend {
    padding: 0;
    margin: 0 0 1rem 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary);
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.question-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    background-color: var(--accent-color);
    color: white;
    border-radius: 50%;
    font-size: 0.9rem;
    font-weight: 600;
    flex-shrink: 0;
}

.required {
    color: var(--error-color);
    font-weight: bold;
}

/* Help text */
.help-text {
    margin: 0.5rem 0 1rem 0;
    padding: 0.75rem;
    background-color: rgba(59, 130, 246, 0.1);
    border-left: 3px solid var(--focus-color);
    color: var(--text-secondary);
    font-size: 0.9rem;
    border-radius: 0 4px 4px 0;
}

