.submit-btn {
    width: 100%;
    padding: 1rem;
    margin-top: 1.5rem;
    background: linear-gradient(135deg, var(--accent-color), var(--focus-color));
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
    box-shadow: 0 10px 15px -3px rgba(139, 92, 246, 0.3);
}

.submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 20px 25px -5px rgba(139, 92, 246, 0.4);
}

.submit-btn:active {
    transform: translateY(0);
}

.submit-btn:focus-visible {
    outline: 2px solid var(--focus-color);
    outline-offset: 2px;
}

/* Results section */
.results {
    margin-top: 2rem;
    padding: 1.5rem;
    background-color: var(--tertiary-bg);
    border: 1px solid var(--border-color);
    border-radius: 8px;
}

.results h2 {
    margin-top: 0;
    color: var(--text-primary);
}

.result-item {
    margin-bottom: 1rem;
    padding: 1rem;
    background-color: rgba(148, 163, 184, 0.05);
    border-radius: 6px;
    border-left: 4px solid var(--accent-color);
}

.result-question {
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 0.5rem;
}

.result-answer {
    color: var(--text-secondary);
