const quizQuestions = {
    question1: {
        title: 'Which of the following languages are interpreted?',
        correctAnswers: ['python', 'javascript', 'ruby'],
        userAnswers: ['python', 'javascript'], // Example for display
    },
    question2: {
        title: 'Which languages were designed with object-oriented programming (OOP) as a primary feature?',
        correctAnswers: ['java', 'csharp', 'php'],
        userAnswers: ['java'],
    },
    question3: {
        title: 'Which of the following are functional programming languages?',
        correctAnswers: ['haskell', 'lisp'],
        userAnswers: ['haskell', 'lisp', 'kotlin'],
    },
};

// Get form reference
const quizForm = document.getElementById('quizForm');
const resultsDiv = document.getElementById('results');
const resultsContent = document.getElementById('resultsContent');

// Handle form submission
quizForm.addEventListener('submit', function (e) {
    e.preventDefault();

    // Get all checked answers
    const formData = new FormData(quizForm);
    const userAnswers = {
        question1: formData.getAll('question1'),
        question2: formData.getAll('question2'),
        question3: formData.getAll('question3'),
    };

    // Calculate results
    const results = calculateResults(userAnswers);

    // Display results
    displayResults(results, userAnswers);

    // Scroll to results
    resultsDiv.scrollIntoView({ behavior: 'smooth' });
});

/**
 * Calculate quiz results by comparing user answers with correct answers
 * @param {Object} userAnswers - User's selected answers
 * @returns {Object} Results with scores and feedback
 */
function calculateResults(userAnswers) {
    let totalScore = 0;
    const questionResults = [];

    Object.entries(userAnswers).forEach(([questionKey, answers]) => {
        const correctAnswers = quizQuestions[questionKey].correctAnswers;

        // Check if user's answers match correct answers exactly
        const isCorrect =
            answers.length === correctAnswers.length &&
            answers.every(answer => correctAnswers.includes(answer));

        const score = isCorrect ? 1 : 0;
        totalScore += score;

        questionResults.push({
            question: quizQuestions[questionKey].title,
            isCorrect,
            userAnswers: answers,
            correctAnswers,
        });
    });

    const percentageScore = (totalScore / 3) * 100;

    return {
        totalScore,
        percentageScore,
        questionResults,
    };
}

/**
 * Display quiz results
 * @param {Object} results - Calculated results
 * @param {Object} userAnswers - User's answers
 */
function displayResults(results, userAnswers) {
    // Build results HTML
    let html = `
        <div style="text-align: center; margin-bottom: 2rem;">
            <div style="font-size: 3rem; font-weight: bold; color: #8b5cf6;">
                ${Math.round(results.percentageScore)}%
            </div>
            <div style="font-size: 1.1rem; color: #cbd5e1; margin-top: 0.5rem;">
                You scored ${results.totalScore} out of 3
            </div>
        </div>
    `;

    // Add detailed feedback for each question
    results.questionResults.forEach((result, index) => {
        const statusClass = result.isCorrect ? 'correct' : 'incorrect';
        const statusIcon = result.isCorrect ? '✓' : '✗';
        const statusColor = result.isCorrect ? '#10b981' : '#ef4444';

        html += `
            <div class="result-item" style="border-left-color: ${statusColor};">
                <div class="result-question">
                    <span style="color: ${statusColor}; font-size: 1.3rem; margin-right: 0.5rem;">${statusIcon}</span>
                    Question ${index + 1}: ${result.question}
                </div>
        `;

        if (result.isCorrect) {
            html += `<div class="result-answer" style="color: #10b981;">✓ Correct!</div>`;
        } else {
            html += `
                <div class="result-answer"><strong>Your answer:</strong> ${
                    result.userAnswers.length > 0
                        ? result.userAnswers.join(', ')
                        : 'No answer selected'
                }</div>
                <div class="result-answer"><strong>Correct answer:</strong> ${result.correctAnswers.join(', ')}</div>
            `;
        }

        html += `</div>`;
    });

    resultsContent.innerHTML = html;
    resultsDiv.hidden = false;
    quizForm.hidden = true;
}
